create table t1(id integer primary key, a integer, b text, c real, d blob)
create table t2(x, y, z)
create table if not exists t3(k integer primary key, v blob)
create table [t4 x](q)
create table if not exists t3(k integer primary key, v blob)
update t1 set b = b || '-upd' where id % 7 = 0
update t1 set a = a + 1 where id < 100
update t1 set id = id + 10000 where id % 50 = 0
update t1 set d = x'' where id % 300 = 5
update t3 set v = x'00ff' where k % 3 = 0
update t2 set y = 'changed' where x between 100 and 199
delete from t1 where id between 500 and 1500
delete from t2 where x % 3 = 0
delete from t3 where k % 2 = 0
delete from t1 where a > 500000000
delete from t2
delete from t1 where id > 0
update t1 set a = 0, b = null where id > 1000
delete from t3
delete from [t4 x] where q is null
